class Inspect(HTMLParser):
 def __init__(self):super().__init__(convert_charrefs=True);self.links=[];self.ids=[];self.pre={};self.active=None
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if'id'in a:self.ids.append(a['id'])
  if tag=='a'and'href'in a:self.links.append(a['href'])
  if tag=='pre'and a.get('id','').startswith('source-code-'):self.active=a['id'];self.pre[self.active]=''
 def handle_data(self,value):
  if self.active:self.pre[self.active]+=value
 def handle_endtag(self,tag):
  if tag=='pre':self.active=None

def main():
 parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--check-only',action='store_true');args=parser.parse_args();d=inputs()
 style=re.search(r'<style>(.*?)</style>',(ROOT/'analysis/phase24/index.html').read_text(),re.S).group(1)
 sources=[]
 for i,s in enumerate(d['sources'],1):sources.append('<details class="source"><summary>'+html.escape(s['name'])+'</summary><p><a href="'+s['path']+'">完整UTF-8源文件</a> · SHA256 <code>'+s['sha256']+'</code></p><pre id="source-code-'+str(i)+'">'+html.escape(s['text'])+'</pre></details>')
 payload={k:v for k,v in d.items()if k!='sources'}
 page=TEMPLATE.replace('__STYLE__',style).replace('__SOURCES__','\n'.join(sources)).replace('__DATA__',json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c'))
 inspector=Inspect();inspector.feed(page);assert len(inspector.ids)==len(set(inspector.ids))
 for i,s in enumerate(d['sources'],1):assert inspector.pre['source-code-'+str(i)]==s['text']
 missing=[]
 for href in inspector.links:
  if href.startswith(('#','http:','https:')):continue
  if not(OUT/href.split('#')[0]).exists()and href not in('package-receipt.json',):missing.append(href)
 assert not missing,missing
 js=re.findall(r'<script>(.*?)</script>',page,re.S)[0];node=shutil.which('node');assert node,'Node is needed for static JS syntax QA'
 result=subprocess.run([node,'--check'],input=js,text=True,capture_output=True);assert result.returncode==0,result.stderr
 if not args.check_only:(OUT/'index.html').write_text(page)
 print(json.dumps(dict(status='static_checks_passed'if args.check_only else'built_static_checks_passed',HTML_created=not args.check_only,HTML_sha256=hashlib.sha256(page.encode()).hexdigest(),HTML_bytes=len(page.encode()),source_modules=2,source_UTF8_exact=True,unique_DOM_ids=len(inspector.ids),local_links=len(inspector.links),missing_links=missing,JS_syntax_passed=True,native_routes=2,native_points=sum(len(r['points'])for r in d['routes']),critical_events=sum(len(r['events'])for r in d['routes']),services=len(d['service_search']),acceptance_dimensions=len(d['acceptance']['dimensions']),source_CPU_cases=0,Native_runs=0)))
if __name__=='__main__':main()
